### Customize html2canvas Rendering with Configuration Options (JavaScript)

Source: https://context7.com/niklasvh/html2canvas/llms.txt

Provides examples of using configuration options to customize html2canvas rendering behavior. Options cover canvas dimensions, background color, image handling (like CORS and timeouts), logging, rendering strategies, window/element dimensions, and element filtering. Dependencies: html2canvas library.

```javascript
// Comprehensive configuration example
html2canvas(document.querySelector('#target'), {
    // Canvas dimensions and positioning
    width: 1024,
    height: 768,
    x: 0,
    y: 0,
    scale: 2, // High DPI rendering (2x device pixel ratio)

    // Background color (default: #ffffff)
    backgroundColor: '#f0f0f0',
    // Use null for transparent background
    // backgroundColor: null,

    // Image handling
    allowTaint: false, // Allow cross-origin images to taint canvas
    useCORS: true,     // Use CORS to load cross-origin images
    imageTimeout: 15000, // Image load timeout in ms (0 = no timeout)
    proxy: 'https://my-proxy.com/proxy', // Proxy URL for cross-origin images

    // Rendering options
    logging: true, // Enable console logging for debugging
    foreignObjectRendering: false, // Use SVG foreignObject if available
    removeContainer: true, // Clean up temporary cloned DOM

    // Window dimensions (affects media queries)
    windowWidth: window.innerWidth,
    windowHeight: window.innerHeight,
    scrollX: window.pageXOffset,
    scrollY: window.pageYOffset,

    // Element filtering
    ignoreElements: function(element) {
        // Exclude elements with specific class
        return element.classList.contains('no-screenshot');
    },

    // DOM manipulation after cloning
    onclone: function(clonedDoc) {
        // Modify cloned document before rendering
        clonedDoc.getElementById('sensitive-info').style.display = 'none';
    }
}).then(canvas => {
    document.body.appendChild(canvas);
});
```

--------------------------------

### Handle Canvas Size Limitations with html2canvas

Source: https://github.com/niklasvh/html2canvas/blob/master/docs/faq.md

Addresses scenarios where the produced canvas is empty or cut off due to browser limitations on canvas size. This snippet demonstrates how to use the `windowWidth` and `windowHeight` options to set a custom window size based on the element's scroll dimensions, potentially avoiding these limitations.

```javascript
await html2canvas(element, {
    windowWidth: element.scrollWidth,
    windowHeight: element.scrollHeight
});
```

--------------------------------

### Handle Cross-Origin Images with html2canvas (CORS/Proxy)

Source: https://context7.com/niklasvh/html2canvas/llms.txt

This snippet demonstrates how to configure html2canvas to handle cross-origin images by either enabling CORS support (requires server configuration) or by specifying a proxy server. It includes examples for both methods and a mixed approach with error handling. The library needs to be included, and the server must be set up correctly for CORS.

```javascript
html2canvas(document.body, {
    useCORS: true,
    allowTaint: false
}).then(canvas => {
    document.body.appendChild(canvas);
});

html2canvas(document.body, {
    proxy: 'https://my-server.com/html2canvas-proxy',
    imageTimeout: 10000
}).then(canvas => {
    document.body.appendChild(canvas);
}).catch(err => {
    console.error('Proxy loading failed:', err);
});

async function captureWithImages() {
    try {
        const canvas = await html2canvas(document.body, {
            useCORS: true,
            logging: false
        });
        return canvas;
    } catch (error) {
        console.warn('CORS failed, trying with proxy');
        return await html2canvas(document.body, {
            proxy: 'https://proxy.example.com/cors',
            allowTaint: false
        });
    }
}

captureWithImages().then(canvas => {
    const dataUrl = canvas.toDataURL('image/png');
    console.log('Screenshot captured:', dataUrl);
});
```

--------------------------------

### Manipulate Cloned Document Before Rendering with html2canvas

Source: https://context7.com/niklasvh/html2canvas/llms.txt

Utilize the 'onclone' callback to modify a cloned document before html2canvas renders it. This allows for dynamic content replacement, element hiding, or adding watermarks without altering the original DOM. Dependencies: html2canvas.

```javascript
html2canvas(document.querySelector('#invoice'), {
    onclone: function(clonedDoc) {
        // Add watermark to screenshot only
        const watermark = clonedDoc.createElement('div');
        watermark.textContent = 'CONFIDENTIAL';
        watermark.style.cssText = 'position:absolute;top:50%;left:50%;' +
            'transform:translate(-50%,-50%) rotate(-45deg);' +
            'font-size:72px;opacity:0.3;color:red;pointer-events:none;';
        clonedDoc.body.appendChild(watermark);

        // Hide elements that should not appear in screenshot
        const privateElements = clonedDoc.querySelectorAll('.edit-button');
        privateElements.forEach(el => el.style.display = 'none');

        // Replace dynamic content with static values
        const dateElement = clonedDoc.querySelector('.current-time');
        if (dateElement) {
            dateElement.textContent = new Date().toLocaleString();
        }

        // Expand all collapsed sections
        const collapsibles = clonedDoc.querySelectorAll('.collapsed');
        collapsibles.forEach(el => el.classList.remove('collapsed'));
    },
    backgroundColor: '#ffffff',
    scale: 2
}).then(canvas => {
    const img = canvas.toDataURL('image/jpeg', 0.95);
    console.log('Modified screenshot ready');
});
```

Source: https://github.com/niklasvh/html2canvas/blob/master/docs/faq.md

Why is the produced canvas empty or cuts off half way through?: Make sure that `canvas` element doesn't hit [browser limitations](https://stackoverflow.com/questions/6081483/maximum-size-of-a-canvas-element) for the `canvas` size or use the window configuration options to set a custom window size based on the `canvas` element:

