### Save PDF Document (Browser)

Source: https://github.com/parallax/jspdf/blob/master/docs/jspdf.js.html

Saves the generated PDF document as a file in the browser using FileSaver.js. Supports returning a Promise for asynchronous operations.

```javascript
API.save = function(filename, options) {
  filename = filename || "generated.pdf";

  options = options || {};
  options.returnPromise = options.returnPromise || false;

  // @if MODULE_FORMAT!='cjs'
  if (options.returnPromise === false) {
    saveAs(getBlob(buildDocument()), filename);
    if (typeof saveAs.unload === "function") {
      if (globalObject.setTimeout) {
        setTimeout(saveAs.unload, 911);
      }
    }
    return this;
  } else {
    return new Promise(function(resolve, reject) {
      try {
        var result = saveAs(getBlob(buildDocument()), filename);
        if (typeof saveAs.unload === "function") {
          if (globalObject.setTimeout) {
            setTimeout(saveAs.unload, 911);
          }
        }
        resolve(result);
      } catch (e) {
        reject(e.message);
      }
    });
  }
  // @endif

  // @if MODULE_FORMAT='cjs'
  // eslint-disable-next-line no-unreachable
  var fs = require("fs");
  var buffer = Buffer.from(getArrayBuffer(buildDocument()));
  if (options.returnPromise === false) {
    fs.writeFileSync(filename, buffer);
  } else {
    return new Promise(function(resolve, reject) {
      fs.writeFile(filename, buffer, function(err) {
        if (err) {
          reject(err);
        } else {
          resolve();
        }
      });
    });
  }
